922    static FT_Error
   923    TT_Process_Simple_Glyph( TT_Loader  loader )
   924    {
   925      FT_GlyphLoader  gloader = loader->gloader;
   926      FT_Error        error   = FT_Err_Ok;
   927      FT_Outline*     outline;
   928      FT_Vector*      unrounded;
   929      FT_Int          n_points;
   930
   931
   932      outline  = &gloader->current.outline;
   933      n_points = outline->n_points;
   934
   935      /* set phantom points */
   936
   937      outline->points[n_points    ] = loader->pp1;
   938      outline->points[n_points + 1] = loader->pp2;
   939      outline->points[n_points + 2] = loader->pp3;
   940      outline->points[n_points + 3] = loader->pp4;
   941
   942      outline->tags[n_points    ] = 0;
   943      outline->tags[n_points + 1] = 0;
   944      outline->tags[n_points + 2] = 0;
   945      outline->tags[n_points + 3] = 0;
   946
   947      n_points += 4;
   948
   949  #ifdef TT_CONFIG_OPTION_GX_VAR_SUPPORT
   950
   951      if ( FT_IS_NAMED_INSTANCE( FT_FACE( loader->face ) ) ||
   952           FT_IS_VARIATION( FT_FACE( loader->face ) )      )
   953      {
   954        /* Deltas apply to the unscaled data.                           */
   955        /* We temporarily use `extra_points2' to hold unrounded values. */
   956        unrounded = gloader->current.extra_points2;
   957        error = TT_Vary_Apply_Glyph_Deltas( loader->face,
   958                                            loader->glyph_index,
   959                                            outline,
   960                                            unrounded,
   961                                            (FT_UInt)n_points );
   962
   963        /* recalculate linear horizontal and vertical advances */
   964        /* if we don't have HVAR and VVAR, respectively        */
   965
   966        /* XXX: change all FreeType modules to store `linear' and `vadvance' */
   967        /*      in 26.6 format before the `base' module scales them to 16.16 */
   968        if ( !( loader->face->variation_support & TT_FACE_FLAG_VAR_HADVANCE ) )
   969          loader->linear = FT_PIX_ROUND( unrounded[n_points - 3].x -
   970                                         unrounded[n_points - 4].x ) / 64;
   971        if ( !( loader->face->variation_support & TT_FACE_FLAG_VAR_VADVANCE ) )
   972          loader->vadvance = FT_PIX_ROUND( unrounded[n_points - 1].x -
   973                                           unrounded[n_points - 2].x ) / 64;
   974
   975        if ( error )
   976          return error;
   977      }
   978
   979  #endif /* TT_CONFIG_OPTION_GX_VAR_SUPPORT */
   980
   981      {
   982  #ifdef TT_SUPPORT_SUBPIXEL_HINTING_INFINALITY
   983        TT_Face    face   = loader->face;
   984        TT_Driver  driver = (TT_Driver)FT_FACE_DRIVER( face );
   985
   986        FT_String*  family         = face->root.family_name;
   987        FT_UInt     ppem           = loader->size->metrics->x_ppem;
   988        FT_String*  style          = face->root.style_name;
   989        FT_UInt     x_scale_factor = 1000;
   990  #endif
   991
   992        FT_Vector*  vec   = outline->points;
   993        FT_Vector*  limit = outline->points + n_points;
   994
   995        FT_Fixed  x_scale = 0; /* pacify compiler */
   996        FT_Fixed  y_scale = 0;
   997
   998        FT_Bool  do_scale = FALSE;
   999
  1000
  1001  #ifdef TT_SUPPORT_SUBPIXEL_HINTING_INFINALITY
  1002
  1003        if ( driver->interpreter_version == TT_INTERPRETER_VERSION_38 )
  1004        {
  1005          /* scale, but only if enabled and only if TT hinting is being used */
  1006          if ( IS_HINTED( loader->load_flags ) )
  1007            x_scale_factor = sph_test_tweak_x_scaling( face,
  1008                                                       family,
  1009                                                       ppem,
  1010                                                       style,
  1011                                                       loader->glyph_index );
  1012          /* scale the glyph */
  1013          if ( ( loader->load_flags & FT_LOAD_NO_SCALE ) == 0 ||
  1014               x_scale_factor != 1000                         )
  1015          {
  1016            x_scale = FT_MulDiv( loader->size->metrics->x_scale,
  1017                                 (FT_Long)x_scale_factor, 1000 );
  1018            y_scale = loader->size->metrics->y_scale;
  1019
  1020            /* compensate for any scaling by de/emboldening; */
  1021            /* the amount was determined via experimentation */
  1022            if ( x_scale_factor != 1000 && ppem > 11 )
  1023            {
  1024              FT_Vector*  orig_points = outline->points;
  1025
  1026
  1027              outline->points = unrounded;
  1028              FT_Outline_EmboldenXY( outline,
  1029                                     FT_MulFix( 1280 * ppem,
  1030                                                1000 - x_scale_factor ),
  1031                                     0 );
  1032              outline->points = orig_points;
  1033            }
  1034            do_scale = TRUE;
  1035          }
  1036        }
  1037        else
  1038
  1039  #endif /* TT_SUPPORT_SUBPIXEL_HINTING_INFINALITY */
  1040
  1041        {
  1042          /* scale the glyph */
  1043          if ( ( loader->load_flags & FT_LOAD_NO_SCALE ) == 0 )
  1044          {
  1045            x_scale = loader->size->metrics->x_scale;
  1046            y_scale = loader->size->metrics->y_scale;
  1047
  1048            do_scale = TRUE;
  1049          }
  1050        }
  1051
  1052        if ( do_scale )
  1053        {
  1054          for ( ; vec < limit; vec++, unrounded++ )
  1055          {
  1056            vec->x = FT_MulDiv( unrounded->x, x_scale, 0x10000L * 64 );
  1057            vec->y = FT_MulDiv( unrounded->y, y_scale, 0x10000L * 64 );
  1058          }
  1059        }
